<?php require __DIR__.'/../helpers/lending.php';$u=lender_user();$requests=lender_rows("SELECT r.*,u.user_fn,u.user_ln FROM borrower_loan_requests r JOIN users u ON u.user_id=r.borrower_id WHERE r.lender_id=? ORDER BY r.created_at DESC",[$u['user_id']]);?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Borrower loan requests</title><link rel="stylesheet" href="../assets/css/integ-lender/lender-flow.css?v=20261010"><link rel="stylesheet" href="../assets/css/borrower-portal.css"><?php uw_role_design_assets('lender', basename(__FILE__, '.php')); ?><link rel="stylesheet" href="../assets/css/integ-lender/lender-live.css"></head><body><div class="admin-layout"><?php $lenderAccount=$u; require __DIR__.'/../helpers/lender_sidebar.php'; ?><main class="main-content"><?php require __DIR__.'/../helpers/lender_topbar.php'; ?><div class="live-body"><a href="dashboard.php">Back to lender dashboard</a><h1>Borrower loan requests</h1><?php foreach($requests as $r): ?><section class="portal-card"><h2>REQ-<?= $r['request_id'] ?> · <?= e($r['user_fn'].' '.$r['user_ln']) ?></h2><p><?= money($r['amount']) ?> · <?= $r['term_months'] ?> months · <?= e($r['purpose']) ?></p><p>Status: <?= e($r['status']) ?></p><a href="loaners.php?view_id=<?= $r['borrower_id'] ?>">View borrower profile</a><?php if($r['status']==='pending'): ?><form class="portal-form" data-request-decision><?php csrf(); ?><input type="hidden" name="action" value="decide-loan-request"><input type="hidden" name="request_id" value="<?= $r['request_id'] ?>"><label>Decision<select name="decision"><option value="approved">Approve</option><option value="rejected">Reject</option></select></label><label>Principal (PHP)<input name="principal" type="number" min="1" max="1000000" step=".01" value="<?= e($r['amount']) ?>"></label><label>Flat monthly interest (%)<input name="monthly_interest_percent" type="number" min="0" max="100" step=".0001" value="0"></label><label>Months<select name="term_months"><?php foreach([3,6,12] as $n): ?><option <?= (int)$r['term_months']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><label>Planned release<input name="release_date" type="date" value="<?= date('Y-m-d') ?>"></label><label>First due date<input name="first_due_date" type="date" value="<?= monthly_due_date(date('Y-m-d'),1) ?>"></label><label>Purpose<textarea name="purpose"><?= e($r['purpose']) ?></textarea></label><p data-estimate></p><label>Rejection reason<textarea name="reason" maxlength="2000"></textarea></label><label class="check"><input type="checkbox" name="confirm_terms" value="yes">I have reviewed these agreement terms.</label><p data-error role="alert"></p><button>Send decision</button></form><?php else: ?><p><?= e($r['reason']) ?></p><?php endif; ?></section><?php endforeach; if(!$requests): ?><p>No repeat-loan requests yet.</p><?php endif; ?></div></main></div><script src="../assets/vendor/sweetalert2/sweetalert2.all.min.js"></script><script src="../assets/js/lender-repeat-requests.js?v=20261010"></script><?php uw_success_assets(); ?><script src="../assets/js/lender-notifications.js" defer></script></body></html>